const MA='9933660066825e9a8005c8.58526829';
const B=[[793,765,767,737,10154,818],[768,673,666,761,773,757],[734,733,10153,10152,749,760],[748,708,770,799,10159,1056],[754,753,744,769,774]];
const I=[['hr','cs','da','nl','et','fil'],['fi','fr','de','el','hu','id'],['it','ko','lv','lt','ms','no'],['pl','pt','ro','sk','sl','es'],['sv','th','tr','uk','vi']];
const o=[];
for(let b=0;b<B.length;b++){
  const ids=[640].concat(B[b]).join(',');
  for(let p=1;p<=7;p++){
    o.push({json:{batch:b,page:p,isos:I[b],url:'https://api.lokalise.com/api2/projects/'+MA+'/keys?filter_untranslated=1&include_translations=1&filter_translation_lang_ids='+ids+'&limit=200&page='+p}});
  }
}
return o;

const req=$('Build Targets').all(),res=$input.all();
const T=['hr','cs','da','nl','et','fil','fi','fr','de','el','hu','id','it','ko','lv','lt','ms','no','pl','pt','ro','sk','sl','es','sv','th','tr','uk','vi'];
const keys={},miss={};for(const t of T)miss[t]=[];
let ok=0,bad=0,seen=0;const prob=[];
const isEmpty=v=>{if(typeof v==='string')return v.trim()==='';if(v&&typeof v==='object')return Object.values(v).every(x=>String(x==null?'':x).trim()==='');return true;};
for(let i=0;i<res.length;i++){
  const m=req[i]?req[i].json:{},b=res[i].json||{};
  if(!Array.isArray(b.keys)){bad++;prob.push('b'+m.batch+'p'+m.page);continue;}
  ok++;
  for(const k of b.keys){
    if(k.is_archived)continue;
    seen++;const id=k.key_id;const bi={};
    for(const t of (k.translations||[]))bi[t.language_iso]=t;
    if(!keys[id])keys[id]={key_id:id,key_name:(k.key_name&&(k.key_name.web||k.key_name.other||k.key_name.ios||k.key_name.android))||'',is_plural:!!k.is_plural,tags:k.tags||[],base_words:k.base_words,context:k.context||'',description:k.description||'',char_limit:k.char_limit||0,source:bi.en?bi.en.translation:null};
    else if(keys[id].source==null&&bi.en)keys[id].source=bi.en.translation;
    for(const iso of (m.isos||[])){const t=bi[iso];if(!t)continue;if(isEmpty(t.translation))miss[iso].push({key_id:id,translation_id:t.translation_id});}
  }
}
const s={ok,bad,prob,distinct:Object.keys(keys).length,rows:seen,per:{},total:0,src_empty:0,plural:0};
for(const t of T){s.per[t]=miss[t].length;s.total+=miss[t].length;}
for(const id in keys){if(isEmpty(keys[id].source))s.src_empty++;if(keys[id].is_plural)s.plural++;}
const smp=Object.values(keys).slice(0,10).map(k=>({n:k.key_name,p:k.is_plural,w:k.base_words,t:k.tags,s:typeof k.source==='string'?k.source.slice(0,180):k.source}));
return [{json:{kind:'summary',s,smp}},{json:{kind:'inventory',keys,miss}}];
